head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        adm_tab_co.setSelectedTabIndex(1);
        scwin.showPanCnd(adm_tab_co.getSelectedTabIndex());
        await scwin.setCode();
        await scwin.listSync1();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21205.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_admCoList_OnLoadError
 * @description dts_admCoList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_admCoList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_admCoList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21205.dts_admCoList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_admCoList_OnLoadCompleted
 * @description dts_admCoList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_admCoList_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_admCoList.removeAll();
        }
        if (adm_tab_co.getSelectedTabIndex() === 1) {
            const rcnt = dts_admCoList.getCellData(rowcount, "NO");
            $c.stf.fillGridHeaderTotalCnt(rcnt, panel_page);

        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.dts_admCoList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name adm_tab_co_PreSelChangeNotify
 * @description adm tab co Pre Sel Change Notify 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.adm_tab_co_PreSelChangeNotify = async function(nIndex) {
    try {
        if (nIndex === 1) {
            await scwin.listSync1();
        } else if (nIndex === 2) {
            await scwin.listSync2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21205.adm_tab_co_PreSelChangeNotify" });
    }
};

/**
 * @method
 * @name btn_toexcel_onclick
 * @description 「엑셀 다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toexcel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF21205.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (adm_tab_co.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_adm_co1, {fileName: "현재투자주의환기종목현황", type: "8"});
        } else {
            $c.data.downloadGridViewExcel(grd_adm_co2, {fileName: "투자주의환기종목지정내역", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.btn_toexcel_onclick" });
    }
};

/**
 * @method
 * @name btn_select_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_select_onclick = async function() {
    try {
        if (adm_tab_co.getSelectedTabIndex() === 1) {
            await scwin.listSync1();
        } else {
            await scwin.listSync2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21205.btn_select_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name adm_tab_co_OnSelChanged
 * @description adm tab co On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.adm_tab_co_OnSelChanged = function(nIndex) {
    try {
        scwin.showPanCnd(nIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.adm_tab_co_OnSelChanged" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (gDepCd === '') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21205.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadError
 * @description dts_emp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_emp_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_emp);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21205.dts_emp_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadError
 * @description dts_dep 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_dep_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_dep);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21205.dts_dep_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    gDepCd = js_dep_cd;
    gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync1
 * @description list Sync1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync1 = async function() {
    url += "?SCREN_ID=" + "ULDSTF21205.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTED_SEARCH_ICR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.tabfirco.icr.select.condition" + "&{P}param01=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param02=" + txb_ISUR_CD.getValue() + "&{P}param03=" + cmb_TeamList.getValue() + "&{P}param04=" + cmb_TeamList.getValue() + "&{P}param05=" + cmb_EmpList.getValue() + "&{P}param06=" + cmb_EmpList.getValue();
    const sbmOptions = {
        id : "sbm_dts_admCoList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_admCoList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync2
 * @description list Sync2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync2 = async function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        url += "?SCREN_ID=" + "ULDSTF21205.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LISTED_SEARCH_ICR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listedsearch.tabsecco.icr.select.condition" + "&{P}param01=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param02=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param03=" + cmb_TeamList.getValue() + "&{P}param04=" + cmb_TeamList.getValue() + "&{P}param05=" + cmb_EmpList.getValue() + "&{P}param06=" + cmb_EmpList.getValue() + "&{P}param07=" + edt_SDate.getValue() + // 시작일자
            "&{P}param08=" + edt_EDate.getValue(); // 종료일자

        const sbmOptions = {
            id : "sbm_dts_admCoList",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_admCoList=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showPanCnd
 * @description show Pan Cnd 처리
 * @param {Number} idx idx
 * @returns {void}
 * @hidden N
 */
scwin.showPanCnd = function(idx) {
    pan_cnd.style.display = (idx === 1 ? "none" : "");
};
